    fn transform(&self, input: f64) -> f64;
}

struct Doubler;
impl Transformer for Doubler {
    fn transform(&self, input: f64) -> f64 { input * 2.0 }
}

struct Squarer;
impl Transformer for Squarer {
    fn transform(&self, input: f64) -> f64 { input * input }
}

fn apply_transformer(input: f64, t: &dyn Transformer) -> f64 {
